"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[75592],{80198(e,a,n){n.r(a),n.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"cursos/solid/modulos/introduccion-solid/cuestionario","title":"cuestionario","description":"2. [Investigar] Kevlin Henney ha criticado p\xfablicamente SOLID en varias conferencias. \xbfCu\xe1les son sus tres cr\xedticas principales y qu\xe9 evidencia presenta? Mencion\xe1 al menos una charla espec\xedfica donde las expuso.","source":"@site/docs/cursos/solid/modulos/01-introduccion-solid/cuestionario.md","sourceDirName":"cursos/solid/modulos/01-introduccion-solid","slug":"/cursos/solid/modulos/introduccion-solid/cuestionario","permalink":"/sasf-temarios/cursos/solid/modulos/introduccion-solid/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/solid/modulos/introduccion-solid/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/solid/modulos/introduccion-solid/ejercicio"}}');var i=n(74848),s=n(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,t={},l=[{value:"2. [Investigar] Kevlin Henney ha criticado p\xfablicamente SOLID en varias conferencias. \xbfCu\xe1les son sus tres cr\xedticas principales y qu\xe9 evidencia presenta? Mencion\xe1 al menos una charla espec\xedfica donde las expuso.",id:"2-investigar-kevlin-henney-ha-criticado-p\xfablicamente-solid-en-varias-conferencias-cu\xe1les-son-sus-tres-cr\xedticas-principales-y-qu\xe9-evidencia-presenta-mencion\xe1-al-menos-una-charla-espec\xedfica-donde-las-expuso",level:3},{value:"3. [Investigar] El Common Closure Principle (CCP) de Robert C. Martin se solapa con SRP. \xbfEn qu\xe9 se diferencian y en qu\xe9 contexto aplica cada uno? Cit\xe1 la fuente original de CCP y explic\xe1 por qu\xe9 Martin sinti\xf3 necesario definirlo por separado.",id:"3-investigar-el-common-closure-principle-ccp-de-robert-c-martin-se-solapa-con-srp-en-qu\xe9-se-diferencian-y-en-qu\xe9-contexto-aplica-cada-uno-cit\xe1-la-fuente-original-de-ccp-y-explic\xe1-por-qu\xe9-martin-sinti\xf3-necesario-definirlo-por-separado",level:3},{value:"4. [Investigar] \xbfQu\xe9 rol espec\xedfico jug\xf3 Michael Feathers en la creaci\xf3n del acr\xf3nimo SOLID? \xbfC\xf3mo y cu\xe1ndo ocurri\xf3 exactamente la &quot;reorganizaci\xf3n&quot; de los principios? \xbfQu\xe9 principio fue el \xfaltimo en agregarse y por qu\xe9?",id:"4-investigar-qu\xe9-rol-espec\xedfico-jug\xf3-michael-feathers-en-la-creaci\xf3n-del-acr\xf3nimo-solid-c\xf3mo-y-cu\xe1ndo-ocurri\xf3-exactamente-la-reorganizaci\xf3n-de-los-principios-qu\xe9-principio-fue-el-\xfaltimo-en-agregarse-y-por-qu\xe9",level:3},{value:"5. [Conectar] Relacion\xe1 el concepto de &quot;deuda t\xe9cnica&quot; de Ward Cunningham con el &quot;costo del cambio&quot; que Robert Martin describe en SOLID. \xbfC\xf3mo se conectan estos conceptos con el libro &quot;The Economics of Software Quality&quot; de Capers Jones y Olivier Bonsignour?",id:"5-conectar-relacion\xe1-el-concepto-de-deuda-t\xe9cnica-de-ward-cunningham-con-el-costo-del-cambio-que-robert-martin-describe-en-solid-c\xf3mo-se-conectan-estos-conceptos-con-el-libro-the-economics-of-software-quality-de-capers-jones-y-olivier-bonsignour",level:3},{value:"6. [Conectar] \xbfC\xf3mo se relacionan los code smells identificados en clase (God Class, Long Method, Shotgun Surgery) con el concepto de &quot;Design Stamina Hypothesis&quot; de Martin Fowler? \xbfQu\xe9 evidencia respalda que el buen dise\xf1o paga la inversi\xf3n?",id:"6-conectar-c\xf3mo-se-relacionan-los-code-smells-identificados-en-clase-god-class-long-method-shotgun-surgery-con-el-concepto-de-design-stamina-hypothesis-de-martin-fowler-qu\xe9-evidencia-respalda-que-el-buen-dise\xf1o-paga-la-inversi\xf3n",level:3},{value:"7. [Conectar] La complejidad ciclom\xe1tica de McCabe (1976) se menciona en clase. \xbfC\xf3mo se relaciona espec\xedficamente esta m\xe9trica con el principio OCP? Investig\xe1 y explic\xe1 por qu\xe9 un m\xe9todo con alta complejidad ciclom\xe1tica casi siempre viola OCP, usando el concepto de &quot;puntos de variaci\xf3n&quot; de la ingenier\xeda de software.",id:"7-conectar-la-complejidad-ciclom\xe1tica-de-mccabe-1976-se-menciona-en-clase-c\xf3mo-se-relaciona-espec\xedficamente-esta-m\xe9trica-con-el-principio-ocp-investig\xe1-y-explic\xe1-por-qu\xe9-un-m\xe9todo-con-alta-complejidad-ciclom\xe1tica-casi-siempre-viola-ocp-usando-el-concepto-de-puntos-de-variaci\xf3n-de-la-ingenier\xeda-de-software",level:3},{value:"8. [Cuestionar] David Heinemeier Hansson (DHH, creador de Ruby on Rails) ha argumentado que SOLID promueve &quot;over-engineering&quot; y &quot;anemic domain models&quot;. \xbfEs v\xe1lida esta cr\xedtica? Present\xe1 argumentos a favor y en contra usando ejemplos concretos de Rails vs Spring.",id:"8-cuestionar-david-heinemeier-hansson-dhh-creador-de-ruby-on-rails-ha-argumentado-que-solid-promueve-over-engineering-y-anemic-domain-models-es-v\xe1lida-esta-cr\xedtica-present\xe1-argumentos-a-favor-y-en-contra-usando-ejemplos-concretos-de-rails-vs-spring",level:3},{value:"9. [Cuestionar] \xbfEs realmente el SRP el principio &quot;m\xe1s fundamental&quot; de SOLID, o es una exageraci\xf3n de Robert Martin? Investig\xe1 el trabajo de Yegor Bugayenko (autor de &quot;Elegant Objects&quot;) quien argumenta que SOLID est\xe1 fundamentalmente equivocado en su enfoque. \xbfQu\xe9 propone Bugayenko en su lugar?",id:"9-cuestionar-es-realmente-el-srp-el-principio-m\xe1s-fundamental-de-solid-o-es-una-exageraci\xf3n-de-robert-martin-investig\xe1-el-trabajo-de-yegor-bugayenko-autor-de-elegant-objects-quien-argumenta-que-solid-est\xe1-fundamentalmente-equivocado-en-su-enfoque-qu\xe9-propone-bugayenko-en-su-lugar",level:3},{value:"10. [Cuestionar] Si SOLID fue formulado para Java/C++ en los a\xf1os 90-2000, \xbfes aplicable a lenguajes funcionales como Haskell, Clojure o Elixir? \xbfCu\xe1les principios se traducen naturalmente y cu\xe1les pierden sentido? Investig\xe1 la postura de Mark Seemann (autor de &quot;Dependency Injection in .NET&quot;) sobre este tema.",id:"10-cuestionar-si-solid-fue-formulado-para-javac-en-los-a\xf1os-90-2000-es-aplicable-a-lenguajes-funcionales-como-haskell-clojure-o-elixir-cu\xe1les-principios-se-traducen-naturalmente-y-cu\xe1les-pierden-sentido-investig\xe1-la-postura-de-mark-seemann-autor-de-dependency-injection-in-net-sobre-este-tema",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.h3,{id:"2-investigar-kevlin-henney-ha-criticado-p\xfablicamente-solid-en-varias-conferencias-cu\xe1les-son-sus-tres-cr\xedticas-principales-y-qu\xe9-evidencia-presenta-mencion\xe1-al-menos-una-charla-espec\xedfica-donde-las-expuso",children:"2. [Investigar] Kevlin Henney ha criticado p\xfablicamente SOLID en varias conferencias. \xbfCu\xe1les son sus tres cr\xedticas principales y qu\xe9 evidencia presenta? Mencion\xe1 al menos una charla espec\xedfica donde las expuso."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": Las tres cr\xedticas principales de Kevlin Henney: (1) ",(0,i.jsx)(a.strong,{children:"SOLID es un acr\xf3nimo forzado"}),': Michael Feathers reorganiz\xf3 principios preexistentes para que deletrearan "SOLID", pero no hay cohesi\xf3n real entre ellos \u2014 OCP viene de Bertrand Meyer (1988), LSP de Barbara Liskov (1987), y los dem\xe1s de Robert Martin en \xe9pocas distintas. (2) ',(0,i.jsx)(a.strong,{children:"Las definiciones son ambiguas y circulares"}),': SRP dice "una raz\xf3n para cambiar" pero no define qu\xe9 es una "raz\xf3n"; OCP dice "abierto/cerrado" pero es una paradoja irresoluble en la pr\xe1ctica. (3) ',(0,i.jsx)(a.strong,{children:"SOLID promueve sobre-ingenier\xeda"}),': la aplicaci\xf3n dogm\xe1tica produce explosi\xf3n de clases, indirecci\xf3n innecesaria y arquitecturas que resuelven problemas que nunca ocurrir\xe1n. Henney expuso estas cr\xedticas en su charla "SOLID Deconstruction" (ACCU 2016) y "The SOLID Design Principles Deconstructed" (NDC 2016).']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": Kevlin Henney es un referente respetado en patrones de dise\xf1o y autor de multiples libros. Su cr\xedtica no es que los principios sean falsos, sino que se presentan como un paquete dogm\xe1tico cuando son ideas de \xe9pocas, autores y contextos diferentes. Henney sugiere que es m\xe1s \xfatil estudiar cada principio en su contexto original (Meyer, Liskov) que como parte del acr\xf3nimo."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"3-investigar-el-common-closure-principle-ccp-de-robert-c-martin-se-solapa-con-srp-en-qu\xe9-se-diferencian-y-en-qu\xe9-contexto-aplica-cada-uno-cit\xe1-la-fuente-original-de-ccp-y-explic\xe1-por-qu\xe9-martin-sinti\xf3-necesario-definirlo-por-separado",children:"3. [Investigar] El Common Closure Principle (CCP) de Robert C. Martin se solapa con SRP. \xbfEn qu\xe9 se diferencian y en qu\xe9 contexto aplica cada uno? Cit\xe1 la fuente original de CCP y explic\xe1 por qu\xe9 Martin sinti\xf3 necesario definirlo por separado."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': El CCP fue definido por Robert C. Martin en "Agile Software Development: Principles, Patterns, and Practices" (2003) como parte de los principios de empaquetamiento: "Las clases que cambian por las mismas razones deben estar en el mismo paquete". La diferencia con SRP es de granularidad y direcci\xf3n: ',(0,i.jsx)(a.strong,{children:"SRP"}),' opera a nivel de clase individual y dice "separ\xe1 responsabilidades" (fuerza centr\xedfuga \u2014 separar). ',(0,i.jsx)(a.strong,{children:"CCP"}),' opera a nivel de paquete/m\xf3dulo y dice "agrup\xe1 clases que cambian juntas" (fuerza centr\xedpeta \u2014 juntar). Son complementarios: SRP impide las God Classes, CCP evita que clases relacionadas queden dispersas. Martin necesit\xf3 CCP porque SRP solo dice qu\xe9 separar pero no dice qu\xe9 mantener junto. Un sistema que aplica SRP sin CCP termina con cientos de clases microsc\xf3picas donde un cambio de l\xf3gica de negocio requiere modificar 20 archivos.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': CCP viene de los principios de Granularidad de Paquetes que Martin public\xf3 en 2003, bas\xe1ndose en el trabajo previo sobre m\xe9tricas de acoplamiento. CCP es la versi\xf3n de paquete del SRP: "las clases en un paquete deben ser cerradas contra los mismos tipos de cambios". Es un principio de cohesi\xf3n a nivel de m\xf3dulo, no de clase.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"4-investigar-qu\xe9-rol-espec\xedfico-jug\xf3-michael-feathers-en-la-creaci\xf3n-del-acr\xf3nimo-solid-c\xf3mo-y-cu\xe1ndo-ocurri\xf3-exactamente-la-reorganizaci\xf3n-de-los-principios-qu\xe9-principio-fue-el-\xfaltimo-en-agregarse-y-por-qu\xe9",children:'4. [Investigar] \xbfQu\xe9 rol espec\xedfico jug\xf3 Michael Feathers en la creaci\xf3n del acr\xf3nimo SOLID? \xbfC\xf3mo y cu\xe1ndo ocurri\xf3 exactamente la "reorganizaci\xf3n" de los principios? \xbfQu\xe9 principio fue el \xfaltimo en agregarse y por qu\xe9?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Michael Feathers acu\xf1\xf3 el acr\xf3nimo SOLID alrededor del a\xf1o 2000 despu\xe9s de leer los art\xedculos de Robert C. Martin sobre principios de dise\xf1o. En un intercambio de emails, Feathers not\xf3 que los primeros cinco principios que Martin hab\xeda descrito formaban el acr\xf3nimo SOLID si se ordenaban como SRP, OCP, LSP, ISP, DIP. El "reordenamiento" fue crucial: ISP originalmente no estaba en la lista inicial de Martin como "principio de dise\xf1o de clases" sino como un principio sobre dependencias entre paquetes. Feathers lo movi\xf3 a la posici\xf3n "I" para completar el acr\xf3nimo. El \xfaltimo en agregarse fue DIP \u2014 Martin lo hab\xeda formulado despu\xe9s de SRP y OCP, pero Feathers lo coloc\xf3 al final del acr\xf3nimo porque completaba "SOLID" y adem\xe1s DIP es el que "cierra" la arquitectura (dependencias hacia abstracciones). La primera menci\xf3n p\xfablica del acr\xf3nimo fue en el art\xedculo "Design Principles and Design Patterns" de Martin (2000), donde ya aparece "SOLID" en la introducci\xf3n, acreditando a Feathers.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': La historia del acr\xf3nimo importa porque revela que SOLID no fue concebido como un sistema integrado, sino como una colecci\xf3n de principios independientes reorganizados para formar una palabra memorable. Kevlin Henney y otros cr\xedticos se\xf1alan esto como evidencia de que la "coherencia" de SOLID es en parte artificial.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"5-conectar-relacion\xe1-el-concepto-de-deuda-t\xe9cnica-de-ward-cunningham-con-el-costo-del-cambio-que-robert-martin-describe-en-solid-c\xf3mo-se-conectan-estos-conceptos-con-el-libro-the-economics-of-software-quality-de-capers-jones-y-olivier-bonsignour",children:'5. [Conectar] Relacion\xe1 el concepto de "deuda t\xe9cnica" de Ward Cunningham con el "costo del cambio" que Robert Martin describe en SOLID. \xbfC\xf3mo se conectan estos conceptos con el libro "The Economics of Software Quality" de Capers Jones y Olivier Bonsignour?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Ward Cunningham acu\xf1\xf3 "deuda t\xe9cnica" en 1992 para describir el costo de no alinear el c\xf3digo con el entendimiento actual del dominio. Robert Martin extendi\xf3 esto con el "costo del cambio": sin SOLID, el costo crece exponencialmente; con SOLID, crece linealmente. Capers Jones y Olivier Bonsignour en "The Economics of Software Quality" (2011) cuantifican esto: el costo de corregir un defecto en producci\xf3n es 100 veces mayor que en dise\xf1o. La conexi\xf3n es: (1) La deuda t\xe9cnica (Cunningham) es la causa, (2) el costo del cambio exponencial (Martin) es el s\xedntoma, (3) los datos emp\xedricos de Jones/Bonsignour son la evidencia cuantitativa. Jones documenta que equipos con baja calidad de c\xf3digo (medida por defectos por KLOC) tienen un costo de mantenimiento 3-5x mayor que equipos con alta calidad, validando la hip\xf3tesis de Martin de que el dise\xf1o afecta directamente el costo econ\xf3mico.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La tr\xedada Cunningham-Martin-Jones forma un argumento completo: la deuda t\xe9cnica no es solo una met\xe1fora sino un fen\xf3meno econ\xf3micamente medible. SOLID es la estrategia de prevenci\xf3n; las m\xe9tricas de Jones son la validaci\xf3n. Jones analiz\xf3 m\xe1s de 13,000 proyectos y encontr\xf3 correlaci\xf3n directa entre mal dise\xf1o estructural y sobrecostos."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"6-conectar-c\xf3mo-se-relacionan-los-code-smells-identificados-en-clase-god-class-long-method-shotgun-surgery-con-el-concepto-de-design-stamina-hypothesis-de-martin-fowler-qu\xe9-evidencia-respalda-que-el-buen-dise\xf1o-paga-la-inversi\xf3n",children:'6. [Conectar] \xbfC\xf3mo se relacionan los code smells identificados en clase (God Class, Long Method, Shotgun Surgery) con el concepto de "Design Stamina Hypothesis" de Martin Fowler? \xbfQu\xe9 evidencia respalda que el buen dise\xf1o paga la inversi\xf3n?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': La Design Stamina Hypothesis de Martin Fowler propone que existe un umbral de calidad de dise\xf1o por debajo del cual el proyecto colapsa, y que la inversi\xf3n en dise\xf1o tiene retorno positivo (a diferencia de la creencia de que "el dise\xf1o no vale la pena porque el software siempre se reescribe"). Los code smells son los indicadores tempranos de que un proyecto se acerca al umbral: cada God Class, Long Method o Shotgun Surgery reduce la "stamina" del dise\xf1o. Fowler argumenta, bas\xe1ndose en su experiencia en ThoughtWorks, que el buen dise\xf1o es una ventaja competitiva, no un lujo. La evidencia: proyectos con baja "stamina" (muchos smells) colapsan cuando alcanzan cierta escala. Estudios como el de la Universidad de Delft (2012) mostraron correlaci\xf3n entre code smells y defectos: God Classes ten\xedan 3.5x m\xe1s bugs que clases con SRP.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': Fowler conecta los code smells con una teor\xeda econ\xf3mica del dise\xf1o. Los principios SOLID son la respuesta pr\xe1ctica: cada principio ataca un smell espec\xedfico (SRP \u2192 God Class, OCP \u2192 Switch Statements, LSP \u2192 Refused Bequest, ISP \u2192 Fat Interface, DIP \u2192 Tight Coupling). La "stamina" se mantiene aplicando SOLID incrementalmente.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"7-conectar-la-complejidad-ciclom\xe1tica-de-mccabe-1976-se-menciona-en-clase-c\xf3mo-se-relaciona-espec\xedficamente-esta-m\xe9trica-con-el-principio-ocp-investig\xe1-y-explic\xe1-por-qu\xe9-un-m\xe9todo-con-alta-complejidad-ciclom\xe1tica-casi-siempre-viola-ocp-usando-el-concepto-de-puntos-de-variaci\xf3n-de-la-ingenier\xeda-de-software",children:'7. [Conectar] La complejidad ciclom\xe1tica de McCabe (1976) se menciona en clase. \xbfC\xf3mo se relaciona espec\xedficamente esta m\xe9trica con el principio OCP? Investig\xe1 y explic\xe1 por qu\xe9 un m\xe9todo con alta complejidad ciclom\xe1tica casi siempre viola OCP, usando el concepto de "puntos de variaci\xf3n" de la ingenier\xeda de software.'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': La complejidad ciclom\xe1tica cuenta puntos de decisi\xf3n (if, switch, for, while). Cada punto de decisi\xf3n representa un "punto de variaci\xf3n" \u2014 un lugar donde el comportamiento diverge seg\xfan condiciones. OCP exige que los puntos de variaci\xf3n se implementen mediante polimorfismo (herencia/interfaces), no mediante condicionales. Un m\xe9todo con complejidad ciclom\xe1tica 15 tiene 15 puntos de decisi\xf3n que, en un dise\xf1o OCP, deber\xedan ser 15 implementaciones de una interfaz com\xfan. La relaci\xf3n es inversa: a mayor complejidad ciclom\xe1tica, m\xe1s violaciones OCP concentradas. Investigaciones como las de Basili y Perricone (1984) mostraron que m\xf3dulos con complejidad ciclom\xe1tica >10 ten\xedan 3x m\xe1s defectos. La m\xe9trica de McCabe es efectivamente un "detector de violaciones OCP": si M > 10 en un m\xe9todo que procesa tipos de datos (tax types, payment methods, notification channels), refactoriz\xe1 a Strategy.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La complejidad ciclom\xe1tica no mide OCP directamente pero es su mejor proxy cuantitativo. Un if/switch creciente viola OCP porque cada nuevo caso requiere modificar c\xf3digo existente. La m\xe9trica de McCabe detecta cuantitativamente lo que OCP proh\xedbe cualitativamente."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"8-cuestionar-david-heinemeier-hansson-dhh-creador-de-ruby-on-rails-ha-argumentado-que-solid-promueve-over-engineering-y-anemic-domain-models-es-v\xe1lida-esta-cr\xedtica-present\xe1-argumentos-a-favor-y-en-contra-usando-ejemplos-concretos-de-rails-vs-spring",children:'8. [Cuestionar] David Heinemeier Hansson (DHH, creador de Ruby on Rails) ha argumentado que SOLID promueve "over-engineering" y "anemic domain models". \xbfEs v\xe1lida esta cr\xedtica? Present\xe1 argumentos a favor y en contra usando ejemplos concretos de Rails vs Spring.'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": ",(0,i.jsx)(a.strong,{children:"A favor de DHH"}),': Rails promueve "fat models" donde la l\xf3gica de negocio vive en el modelo ActiveRecord, que es una clase rica (no an\xe9mica). Aplicar SRP estrictamente en Rails producir\xeda cientos de service objects que fragmentan la l\xf3gica. Ejemplo: un modelo ',(0,i.jsx)(a.code,{children:"Order"}),' en Rails tiene validaciones, c\xe1lculos, callbacks y asociaciones \u2014 SRP dir\xeda que tiene "m\xfaltiples razones para cambiar", pero en Rails esto es idiom\xe1tico y productivo. DHH sostiene que la cohesi\xf3n del dominio es m\xe1s valiosa que la pureza de SRP. ',(0,i.jsx)(a.strong,{children:"En contra de DHH"}),': El mismo Martin Fowler acu\xf1\xf3 "anemic domain model" como anti-patr\xf3n, y SRP bien aplicado NO produce modelos an\xe9micos. SRP separa responsabilidades transversales (persistencia, notificaci\xf3n, validaci\xf3n) PERO mantiene la l\xf3gica de dominio junta en el aggregate root (DDD). Spring no exige modelos an\xe9micos; permite modelos ricos con l\xf3gica de dominio. La cr\xedtica de DHH es v\xe1lida contra la aplicaci\xf3n dogm\xe1tica de SOLID, pero no contra los principios en s\xed.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': DHH y Martin representan dos filosof\xedas: "Convention over Configuration" (Rails) vs "Explicit design" (SOLID). La cr\xedtica de DHH (expuesta en "The Rails Doctrine" y m\xfaltiples tweets) apunta a que SOLID industrializa el dise\xf1o creando f\xe1bricas de c\xf3digo donde la l\xf3gica de negocio se diluye en servicios. La defensa de SOLID es que sin estos principios, Rails produce sistemas que colapsan a escala (Shopify y GitHub han tenido que introducir service layers sobre Rails).']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"9-cuestionar-es-realmente-el-srp-el-principio-m\xe1s-fundamental-de-solid-o-es-una-exageraci\xf3n-de-robert-martin-investig\xe1-el-trabajo-de-yegor-bugayenko-autor-de-elegant-objects-quien-argumenta-que-solid-est\xe1-fundamentalmente-equivocado-en-su-enfoque-qu\xe9-propone-bugayenko-en-su-lugar",children:'9. [Cuestionar] \xbfEs realmente el SRP el principio "m\xe1s fundamental" de SOLID, o es una exageraci\xf3n de Robert Martin? Investig\xe1 el trabajo de Yegor Bugayenko (autor de "Elegant Objects") quien argumenta que SOLID est\xe1 fundamentalmente equivocado en su enfoque. \xbfQu\xe9 propone Bugayenko en su lugar?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Yegor Bugayenko, en su libro "Elegant Objects" (2016) y m\xfaltiples art\xedculos, argumenta que SOLID est\xe1 equivocado porque: (1) SRP destruye la cohesi\xf3n al atomizar objetos que deber\xedan ser ricos. Bugayenko defiende objetos que encapsulan estado y comportamiento juntos \u2014 lo opuesto a separar validaci\xf3n, c\xe1lculo y persistencia. (2) DIP es innecesario si los objetos son verdaderamente encapsulados \u2014 un objeto no deber\xeda necesitar que le inyecten dependencias; deber\xeda ser autosuficiente a trav\xe9s de composici\xf3n. (3) Propone principios alternativos: "no hay clases abstractas" (todo debe ser concreto y componible), "no hay getters/setters" (los objetos no exponen estado), "los constructores sin par\xe1metros son malvados". Bugayenko afirma que SOLID es una soluci\xf3n a problemas que no existir\xedan si se usaran objetos reales (con encapsulamiento estricto, inmutabilidad y composici\xf3n) en lugar del estilo procedural que domina Java enterprise.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': Bugayenko es una voz disidente importante porque argumenta desde dentro del ecosistema OOP, no desde fuera. Su cr\xedtica no es "OOP est\xe1 mal" sino "SOLID es un parche sobre mal OOP". Para Bugayenko, un sistema bien dise\xf1ado con objetos verdaderamente encapsulados no necesita SRP porque cada objeto naturalmente tiene una responsabilidad al estar bien definido.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"10-cuestionar-si-solid-fue-formulado-para-javac-en-los-a\xf1os-90-2000-es-aplicable-a-lenguajes-funcionales-como-haskell-clojure-o-elixir-cu\xe1les-principios-se-traducen-naturalmente-y-cu\xe1les-pierden-sentido-investig\xe1-la-postura-de-mark-seemann-autor-de-dependency-injection-in-net-sobre-este-tema",children:'10. [Cuestionar] Si SOLID fue formulado para Java/C++ en los a\xf1os 90-2000, \xbfes aplicable a lenguajes funcionales como Haskell, Clojure o Elixir? \xbfCu\xe1les principios se traducen naturalmente y cu\xe1les pierden sentido? Investig\xe1 la postura de Mark Seemann (autor de "Dependency Injection in .NET") sobre este tema.'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": Seg\xfan Mark Seemann y otros autores: ",(0,i.jsx)(a.strong,{children:"SRP"}),' se traduce como "una funci\xf3n debe hacer una sola cosa" \u2014 es universal y se alinea con el principio de "funciones peque\xf1as y puras" del FP. ',(0,i.jsx)(a.strong,{children:"OCP"}),' se traduce como "higher-order functions" \u2014 en lugar de Strategy Pattern, se pasa una funci\xf3n como par\xe1metro (OCP sin jerarqu\xeda de clases). ',(0,i.jsx)(a.strong,{children:"LSP"})," es irrelevante en FP puro porque no hay herencia de tipos; se reemplaza por el sistema de tipos algebraico (type classes en Haskell, protocols en Elixir). ",(0,i.jsx)(a.strong,{children:"ISP"}),' se traduce como "funciones que aceptan exactamente los datos que necesitan" (record types en lugar de objetos inflados). ',(0,i.jsx)(a.strong,{children:"DIP"}),' se traduce como "depender de funciones, no de m\xf3dulos concretos" \u2014 en FP se logra naturalmente con higher-order functions y type classes. Seemann argumenta que SOLID fue una soluci\xf3n espec\xedfica para las limitaciones de OOP (herencia r\xedgida, acoplamiento impl\xedcito, estado mutable) y que en FP muchos de estos principios son redundantes porque el paradigma ya los incorpora (funciones puras = SRP, HOF = OCP, type classes = ISP).']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": Mark Seemann explor\xf3 esto en su blog y en charlas sobre FP vs OOP. La conclusi\xf3n no es que SOLID sea incorrecto sino que fue formulado para resolver problemas espec\xedficos de un paradigma. En FP, las mismas propiedades deseables (bajo acoplamiento, alta cohesi\xf3n, testabilidad) se logran con mecanismos diferentes."]})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,a,n){n.d(a,{R:()=>r,x:()=>c});var o=n(96540);const i={},s=o.createContext(i);function r(e){const a=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(s.Provider,{value:a},e.children)}}}]);